package com.xfusion.fusiondesk.ai;
import com.xfusion.fusiondesk.config.AppConfig;import com.xfusion.fusiondesk.exception.AiAnalysisException;import java.net.http.HttpClient;import java.time.Duration;
public record LlmProviderSet(LlmProvider primary,LlmProvider fallback,String primaryModel,String fallbackModel){
 public static LlmProviderSet fromConfig(AppConfig c){String key=c.value("LLM_API_KEY","llm.api-key"),base=c.value("LLM_BASE_URL","llm.base-url"),model=c.value("LLM_MODEL","llm.model");LlmProvider primary=provider(base,key,model,c.intValue("llm.primary.connect-timeout-seconds",5),c.intValue("llm.primary.request-timeout-seconds",20));if(!c.booleanValue("llm.fallback.enabled",false))return new LlmProviderSet(primary,null,model,null);String fallbackKey=or(c.value("LLM_FALLBACK_API_KEY","llm.fallback.api-key"),key),fallbackBase=or(c.value("LLM_FALLBACK_BASE_URL","llm.fallback.base-url"),base),fallbackModel=c.value("LLM_FALLBACK_MODEL","llm.fallback.model");if(blank(fallbackModel))throw new AiAnalysisException("Fallback LLM is enabled but llm.fallback.model is missing.");LlmProvider fallback=provider(fallbackBase,fallbackKey,fallbackModel,c.intValue("llm.fallback.connect-timeout-seconds",5),c.intValue("llm.fallback.request-timeout-seconds",20));return new LlmProviderSet(primary,fallback,model,fallbackModel);}
 private static LlmProvider provider(String base,String key,String model,int connect,int request){if(connect<=0||request<=0)throw new AiAnalysisException("LLM timeout configuration must be positive.");return new OpenAiCompatibleLlmProvider(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(connect)).build(),base,key,model,Duration.ofSeconds(request));}
 private static String or(String value,String fallback){return blank(value)?fallback:value;}private static boolean blank(String value){return value==null||value.isBlank();}
}
